def longestPalindromicSubsequence(s: str, k: int) -> int:
    import sys
    from functools import lru_cache
    n = len(s)
    sys.setrecursionlimit(1 << 20)

    def cost(a, b):
        # Minimum operations to make two letters equal (wrap-around alphabet).
        d = abs(ord(a) - ord(b))
        return min(d, 26 - d)

    @lru_cache(maxsize=None)
    def dp(i, j, budget):
        if i > j:
            return 0
        if i == j:
            return 1
        res = max(dp(i + 1, j, budget), dp(i, j - 1, budget))
        c = cost(s[i], s[j])
        if c <= budget:
            res = max(res, 2 + dp(i + 1, j - 1, budget - c))
        return res

    return dp(0, n - 1, k)
